def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    rich_threat = False
    desperate_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
        if opp.get('budget', 0) >= 200 and opp.get('hp', 10) >= 6:
            rich_threat = True
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.4
    if no_water_days >= 1:
        urgency += 0.35
    urgency += scarcity * 0.35
    if desperate_count >= 2:
        urgency += 0.1
    if urgency > 1.0:
        urgency = 1.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    else:
        if highest_prev >= 135:
            bid = DAILY_SALARY * (0.28 + 0.18 * urgency + 0.08 * scarcity)
        elif highest_prev >= 110:
            bid = max(DAILY_SALARY * (0.48 + 0.18 * urgency), highest_prev + 1.25)
        elif highest_prev >= 70:
            bid = max(DAILY_SALARY * (0.42 + 0.16 * urgency), avg_prev + 2.0)
        else:
            bid = DAILY_SALARY * (0.34 + 0.22 * urgency + 0.10 * scarcity)

    if rich_threat and supply <= 18 and hp <= 4:
        bid = max(bid, highest_prev + 1.5)

    reserve_target = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    max_safe = budget - reserve_target
    if hp <= 3:
        max_safe = budget
    elif max_safe < DAILY_SALARY * 0.2:
        max_safe = max(budget * 0.6, DAILY_SALARY * 0.2)

    if bid > max_safe:
        bid = max_safe

    floor_bid = 0.0
    if hp <= 4 or no_water_days >= 1:
        floor_bid = DAILY_SALARY * 0.35
    elif supply <= 17:
        floor_bid = DAILY_SALARY * 0.25

    if bid < floor_bid:
        bid = floor_bid

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    cindy_bid = 0
    for name, opp in opponents_status.items():
        if name == 'Cindy' and opp['alive']:
            prev = opp.get('previous_trace', {})
            cindy_bid = prev.get('bid', 140.0)

    if my_status['hp'] <= 3:
        return min(my_status['budget'], 150.0)

    if cindy_bid > 0 and cindy_bid < my_status['budget']:
        return min(my_status['budget'], cindy_bid + 1.0)

    if supply < 18:
        return min(my_status['budget'], 120.0)

    return min(my_status['budget'], 85.0)
